INSERT INTO hecho_delictivo (id_hecho, id_delito) SELECT (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-04'  ORDER BY h.id_hecho DESC ROWS 1), dc.id_delito_cometido FROM persona p JOIN delito d ON d.codigo = 'AGR-DEL-056' JOIN clasificacion_delito c ON UPPER(TRIM(c.nombre)) = UPPER('Otros') JOIN delito_cometido dc ON dc.id_tipo_delito = d.id_delito AND dc.id_clasificacion_delito = c.id_clasificacion_delito WHERE p.nombres = 'AGR_2023_358198' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho_delictivo hd WHERE hd.id_hecho = (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-10-04'  ORDER BY h.id_hecho DESC ROWS 1)   AND hd.id_delito = dc.id_delito_cometido);
INSERT INTO ubicacion (id_municipio, id_area_geografica, ciudad, zona, direccion_referencia) SELECT m.id_municipio, NULL, NULL, 'Ignorada', NULL FROM departamento d JOIN municipio m ON m.id_departamento = d.id_departamento WHERE UPPER(TRIM(d.nombre)) = UPPER('Alta Verapaz')   AND UPPER(TRIM(m.nombre)) = UPPER('Santa Cruz Verapaz')   AND NOT EXISTS (SELECT 1 FROM ubicacion u WHERE u.id_municipio = m.id_municipio AND COALESCE(u.zona, '') = 'Ignorada');
INSERT INTO persona (nombres, apellidos, fecha_nacimiento, cui, id_genero, id_orientacion_sexual, id_grupo_etnico, id_estado_civil, id_condicion_alfabetica, id_nivel_escolaridad, id_origen, es_extranjero) SELECT 'AGR_2023_358199', 'AGRAVIADOS', '1993-06-15', NULL, COALESCE((SELECT id_genero FROM genero WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1),          (SELECT id_genero FROM genero WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1)), COALESCE((SELECT id_orientacion_sexual FROM orientacion_sexual WHERE UPPER(TRIM(nombre)) IN ('IGNORADO','SIN SELECCION','SD') ORDER BY id_orientacion_sexual ROWS 1),          (SELECT id_orientacion_sexual FROM orientacion_sexual ORDER BY id_orientacion_sexual ROWS 1)), COALESCE((SELECT id_grupo_etnico FROM grupo_etnico WHERE UPPER(TRIM(nombre)) IN ('IGNORADO','SD') ORDER BY id_grupo_etnico ROWS 1),          (SELECT id_grupo_etnico FROM grupo_etnico ORDER BY id_grupo_etnico ROWS 1)), COALESCE((SELECT id_estado_civil FROM estado_civil WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1),          (SELECT id_estado_civil FROM estado_civil WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1)), (SELECT id_condicion_alfabetica FROM condicion_alfabetica WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1), (SELECT id_nivel_escolaridad FROM nivel_escolaridad WHERE UPPER(TRIM(nombre)) = UPPER('Ignorado') ROWS 1), (SELECT u.id_ubicacion FROM ubicacion u  JOIN municipio m ON m.id_municipio = u.id_municipio  JOIN departamento d ON d.id_departamento = m.id_departamento  WHERE UPPER(TRIM(d.nombre)) = UPPER('Alta Verapaz')    AND UPPER(TRIM(m.nombre)) = UPPER('Santa Cruz Verapaz')    AND COALESCE(u.zona, '') = 'Ignorada'  ORDER BY u.id_ubicacion DESC ROWS 1), 0 FROM RDB$DATABASE WHERE NOT EXISTS (SELECT 1 FROM persona p WHERE p.nombres = 'AGR_2023_358199' AND p.apellidos = 'AGRAVIADOS');
INSERT INTO hecho (id_tipo_hecho, id_ubicacion, fecha_hecho) SELECT (SELECT id_tipo_hecho FROM tipo_hecho WHERE UPPER(TRIM(nombre)) = UPPER('hecho_delictivo') ROWS 1), p.id_origen, '2023-09-28' FROM persona p WHERE p.nombres = 'AGR_2023_358199' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho h JOIN involucrado_hecho ih ON ih.id_hecho = h.id_hecho WHERE ih.id_involucrado = p.id_persona   AND h.fecha_hecho = '2023-09-28');
